6	/**
7	 * A class representing shared characteristics of consumers.
8	 *
9	 * @version 18.02.22 (DD:MM:YY)
10	 */
11	public abstract class Consumer extends Actor
12	{
13	    // Properties shared between all consumers:
14	    private static final int STARTING_SUSTENANCE_LEVEL = 20;
15	    private static final double NEW_DISEASE = 0.0005;
16	    private static final double NIGHT_PREY_MISS_PROBABILITY = 0.5;
17	    private static Random rand = Randomizer.getRandom();
18	
19	    // Properties unique to this consumer:
20	    private int breedingAge;
21	    private int sustenanceLevel;
22	    private int maxSustenanceLevel;
23	    private ArrayList<Class> prey;
24	    private Disease disease;
25	    private boolean ifCarcass;
26	    private Carcass newCarcass;
27	    private boolean canEatCarcass;
28	    private boolean primaryConsumer;
29	    
30	    /**
31	     * Create a new consumer at a location in the field.
32	     * 
33	     * @param field               The field currently occupied.
34	     * @param location            The location within the field.
35	     * @param consumptionWorth    The worth of the consumer if consumed.
36	     * @param breedingProbability The liklihood of the consumer breeding.
37	     * @param maxBirthsAtOnce     The max number of births for the consumer.
38	     * @param maxAge              The age to which this consumer can live.
39	     * @param breedingAge         The age at which this consumer can start to breed.
40	     */
41	    public Consumer(Field field, Location location, ArrayList<Class> prey, int consumptionWorth,
42	                    double breedingProbability, int maxBirthsAtOnce, int maxAge, int breedingAge,int maxSustenanceLevel,boolean canEatCarcass,boolean primaryConsumer)
43	    {
44	        super(field, location, consumptionWorth, breedingProbability, maxBirthsAtOnce,maxSustenanceLevel,maxAge);
45	        this.canEatCarcass = canEatCarcass;
46	        this.prey = prey;
47	        this.maxAge = maxAge;
48	        this.breedingAge = breedingAge;
49	        this.primaryConsumer = primaryConsumer;
50	        sustenanceLevel = 30;
51	    }
52	    
53	    /**
54	     * Make this consumer act - that is: make it do
55	     * whatever it wants/needs to do.
56	     * 
57	     * @param newConsumers A list to receive newly born consumers.
58	     */
59	    public void act(List<Actor> newConsumers)
60	    {   
61	        incrementAge();
62	        incrementHunger();
63	        if (getIsAlive())
64	        {
65	            giveBirth(newConsumers);
66	            boolean wasPossibleToMove = huntForFood();
67	            if(ifCarcass)
68	            {
69	                newConsumers.add(newCarcass);
70	                ifCarcass = false;
71	                newCarcass = null;
72	            }
73	            if(hasDisease())
74	            {                                                                                   
75	                diseaseEffect();
76	            }
77	            if (!wasPossibleToMove)
78	            {
79	                setDead();
80	            }
81	        }
82	    }
83	    /**
84	     * Returns true if this consumer is diseased else return false.
85	     * @return boolean
86	     */
87	    private boolean hasDisease()
88	    {
89	        return this.disease != null;
90	    }
91	    /**
92	     * Returns a new Disease.
93	     * @return diseae
94	     */
95	    private Disease giveDisease()
96	    {
97	        return new Disease();
98	    }
99	    /**
100	     * If the animal is diseased then evolve the disease.
101	     */
102	    private void diseaseEffect()
103	    {
104	        if(hasDisease())
105	        {
106	            disease.decrementStepsBeforeDeath();
107	            spreadDisease();
108	            checkForFatalDisease();
109	            incrementHunger();
110	        }
111	    }
112	    /**
113	     * Check if the disease is fatal to the animal.
114	     */
115	    private void checkForFatalDisease()
116	    {
117	        if(hasDisease() && disease.diseaseFinished())
118	        {   
119	            if(disease.isFatal())
120	            {
121	                setDead();
122	            }
123	            disease = null;
124	        }
125	    }
126	    /**
127	     * Spread the disease to different animals of the same species.
128	     */
129	    private void spreadDisease()
130	    {
131	            Field field = getField();
132	            List<Location> adjacent = field.adjacentLocations(getLocation());
133	            Iterator<Location> it = adjacent.iterator();
134	            while(it.hasNext())
135	
136	            {
137	                Location loc = it.next();
138	                Object animal = field.getObjectAt(loc);
139	                Actor consumer = (Actor) animal;
140	                if(consumer != null && consumer.getClass() == this.getClass() && this.hasDisease())
141	                {
142	                    ((Consumer) consumer).disease = giveDisease();
143	                }
144	            }
145	    }
146	    /**
147	     * Hunt for food by moving toward it.
148	     */
149	    private boolean huntForFood()
150	    {
151	        // Move towards a source of food if found:
152	        Location newLocation = findFood();
153	        
154	        if (newLocation == null)
155	        { 
156	            // No food found - try to move to a free location:
157	            newLocation = getField().freeAdjacentLocation(getLocation());
158	        }
159	        
160	        // See if it was possible to move.
161	        if (newLocation != null) setLocation(newLocation);
162	        
163	        return newLocation != null;
164	    }
165	    
166	    /**
167	     * Set the starting age of the consumer, dependent on whether a random
168	     * age has been selected.
169	     * 
170	     * @param randomAge If true, the age is random, otherwise it's 0.
171	     */
172	    protected void setStartingAge(boolean randomAge)
173	    {
174	        if (randomAge) currentAge = rand.nextInt(maxAge) ;
175	        else           currentAge = 0;
176	    }
177	    
178	    
179	    /**
180	     * Check whether or not this consumer is to give birth at this step.
181	     * New births will be made into free adjacent locations.
182	     * 
183	     * @param newConsumers A list to return newly born consumers.
184	     */
185	    private void giveBirth(List<Actor> newConsumers)
186	    {
187	        // Ensure this consumer has a valid mate in a neighboring location before continuing.
188	        if (!checkForValidMate()) return;
189	        
190	        // Get a list of free adjacent locations:
191	        Field field = getField();
192	        List<Location> free = field.getFreeAdjacentLocations(getLocation());
193	        
194	        // Work out the number of births this producer will have this step:
195	        int births = breed();
196	        // Add each birth into an adjacent location:
197	        for (int b = 0; b < births && free.size() > 0; b++)
198	        {
199	            Location location = free.remove(0);
200	            
201	            try
202	            {
203	                Actor child = this.getClass()
204	                              .getDeclaredConstructor(boolean.class,
205	                                                      Field.class,
206	                                                      Location.class)
207	                              .newInstance(true, field, location);
208	                
209	                newConsumers.add(child);
210	            }
211	            catch (java.lang.Exception e)
212	            {
213	                System.out.println("Error!");
214	                
215	                continue;
216	            }
217	        }
218	    }
219	    
220	    /**
221	     * @return True if there is a valid mate in an adjacent location for the consumer.
222	     */
223	    private boolean checkForValidMate()
224	    {   
225	        Field field = getField();
226	        
227	        for (Location location : field.adjacentLocations(getLocation()))
228	        {
229	            Object object = field.getObjectAt(location);
230	            
231	            if (object instanceof Consumer                 // Is there a consumer in that location?
232	                && object.getClass() == this.getClass()    // Is the consumer of the same type as this one?
233	                && ((Consumer) object).canBreed()          // Can that consumer breed?
234	                && ((Actor) object).getGender() != gender) // Is that consumer of the opposite sex?
235	            {
236	                return true; // We have found a valid mate.
237	            }
238	        }
239	        
240	        return false; // We didn't manage to find a valid mate.
241	    }
242	        
243	    /**
244	     * Generate a number representing the number of births,
245	     * if it can breed.
246	     * 
247	     * @return The number of births (may be zero).
248	     */
249	    private int breed()
250	    {
251	        int births = 0;
252	        
253	        boolean willBreed = rand.nextDouble()
254	                            <= getBreedingProbability();
255	                            
256	        if (canBreed() && willBreed)
257	            births = rand.nextInt(getMaxBirthsAtOnce()) + 1;
258	        
259	        return births;
260	    }
261	
262	    /**
263	     * A consumer can breed if it has reached the breeding age.
264	     * 
265	     * @return True if the consumer can breed, false otherwise.
266	     */
267	    private boolean canBreed() { return currentAge >= breedingAge; }
268	    
269	    /**
270	     * Make this consumer more hungry. This could result in the consumer's death.
271	     */
272	    private void incrementHunger()
273	    {
274	        sustenanceLevel--;
275	        if (sustenanceLevel <= 0) setDead();
276	    }
277	    
278	    /**
279	     * Look for prey adjacent to the current location.
280	     * Only the first live prey is eaten.
281	     * 
282	     * @return Where food was found, or null if it wasn't.
283	     */
284	    private Location findFood()
285	    {
286	        // Get adjacent locations:
287	        Field field;
288	        field = getField();
289	        List<Location> adjacentLocations = field.adjacentLocations(getLocation());
290	        
291	        Iterator<Location> it = adjacentLocations.iterator();
292	        
293	        while (it.hasNext())
294	        {
295	            Location where = it.next();
296	            Object object = field.getObjectAt(where);
297	            
298	            for (Class preyClass : prey)
299	            {   
300	                if (preyClass.isInstance(object))
301	                {   
302	                    Actor actor = (Actor) object;
303	                    
304	                    if (actor.getIsAlive())
305	                    {   
306	                        // If it's night, there is a probability of missing the prey:
307	                        if (TimeSystem.isNightTime())
308	                        {   
309	                            if (rand.nextDouble() <= 1.0 - NIGHT_PREY_MISS_PROBABILITY)
310	                            {   
311	                                
312	                                return eat(actor);
313	                            }
314	                        }
315	                        else
316	                        {
317	                            
318	                            return eat(actor);
319	                        }
320	                    }
321	                }
322	            }
323	            if(Carcass.class.isInstance(object))
324	            {   
325	                if(canEatCarcass)
326	                {
327	                    Carcass carcass = (Carcass) object;
328	                    if(carcass.isDiseased())
329	                    {
330	                        this.disease = giveDisease();
331	                    }
332	                    sustenanceLevel += carcass.getConsumptionWorth();
333	                    carcass.setDead();
334	                    return where;
335	                }
336	            }
337	        }
338	        
339	        return null;
340	    }
341	    protected boolean becomeCarcass()
342	    {
343	        return true;
344	    }
345	    /**
346	     * Makes the animal eat the food and generate a carcass if necessary.
347	     * @param actor The actor who is to be eaten.
348	     */
349	    private Location eat(Actor actor)
350	    {   
351	        Location location = actor.getLocation();
352	        int actorConsumptionWorth = actor.getConsumptionWorth();
353	        if(actor.becomeCarcass())
354	        {   
355	            actor.setDead();
356	            if((sustenanceLevel + actorConsumptionWorth) > maxSustenanceLevel)
357	            {   
358	                int foodLeft = (sustenanceLevel + consumptionWorth) - maxSustenanceLevel;
359	                sustenanceLevel = this.maxSustenanceLevel;
360	                Carcass carcass = new Carcass(getField(),location,foodLeft);
361	                newCarcass = carcass;
362	                ifCarcass = true;
363	                return getLocation();
364	            }  
365	        }
366	        if(sustenanceLevel + actorConsumptionWorth <= maxSustenanceLevel)
367	        {
368	            sustenanceLevel += actorConsumptionWorth;
369	            return location;
370	        }
371	        return null;
372	    }
373	}

