1	 import java.util.Random;
2	import java.util.List;
3	import java.util.ArrayList;
4	import java.util.Iterator;
5	import java.awt.Color;
6	import javafx.application.Application;
7	
8	/**
9	 * A simple predator-prey simulator, based on a rectangular field.
10	 *
11	 * @version 18.02.22 (DD:MM:YY)
12	 */
13	public class Simulator
14	{
15	    // Constants representing configuration information for the simulation:
16	    //   The default width for the grid:
17	    private static final int DEFAULT_WIDTH = 120;
18	    //   The default height for the grid:
19	    private static final int DEFAULT_DEPTH = 160;
20	                                                  
21	    // Constants representing the creation probabilities for the actors:
22	    //   Primary consumers:
23	    private static final double GRASSHOPPER_CREATION_PROBABILITY   = 0.15;
24	    private static final double HARVESTER_ANT_CREATION_PROBABILITY = 0.25;
25	    private static final double TERMITE_CREATION_PROBABILITY       = 0.21;
26	    private static final double IMPALA_CREATION_PROBABILITY        = 0.15;
27	    //   Secondary consumers:
28	    private static final double PANGOLIN_CREATION_PROBABILITY      = 0.125;
29	    private static final double AARDVARK_CREATION_PROBABILITY      = 0.12;
30	    private static final double MONGOOSE_CREATION_PROBABILITY      = 0.12;
31	    //   Producers:
32	    private static final double STAR_GRASS_CREATION_PROBABILITY    = 0.05;
33	    private static final double RED_OAT_GRASS_CREATION_PROBABILITY = 0.04;
34	    private static final double ACACIA_CREATION_PROBABILITY        = 0.04;
35	    
36	    // Constants representing the color of each actor in the simulation view:
37	    //   Primary consumers:
38	    private static final Color GRASSHOPPER_COLOR   = new Color(188, 248, 236);
39	    private static final Color HARVESTER_ANT_COLOR = new Color(4, 139, 168);
40	    private static final Color TERMITE_COLOR       = new Color(22, 219, 147);
41	    private static final Color IMPALA_COLOR        = new Color(239, 234, 90);
42	    //   Secondary consumers:
43	    private static final Color PANGOLIN_COLOR      = new Color(242, 158, 76);
44	    private static final Color AARDVARK_COLOR      = new Color(204, 183, 174);
45	    private static final Color MONGOOSE_COLOR      = new Color(65, 69, 53);
46	    //   Producers:
47	    private static final Color STAR_GRASS_COLOR    = new Color(125, 97, 103);
48	    private static final Color RED_OAT_GRASS_COLOR = new Color(164, 3, 111);
49	    private static final Color ACACIA_COLOR        = new Color(187, 214, 134);
50	    // Carcasses of consumers
51	    private static final Color CARCASS_COLOR       = new Color(202,0,0);
52	    
53	    // The number of steps in a day:
54	    public static final int NUMBER_OF_STEPS_PER_DAY = 25;
55	    
56	    // List of actors in the field:
57	    private List<Actor> actors;
58	    // The current state of the field:
59	    private static Field field;
60	    // The current step of the simulation.
61	    private static int step = 0;
62	    // A graphical view of the simulation:
63	    private static SimulatorView view;
64	    // A Boolean indicating whether or not to reset the StatisticsView:
65	    public static boolean resetStatisticsView = false;
66	    
67	    /**
68	     * Construct a simulation field with default size.
69	     */
70	    public Simulator()
71	    {
72	        this(DEFAULT_DEPTH, DEFAULT_WIDTH);
73	    }
74	    
75	    /**
76	     * Create a simulation field with the given size.
77	     * 
78	     * @param depth Depth of the field. Must be greater than zero.
79	     * @param width Width of the field. Must be greater than zero.
80	     */
81	    public Simulator(int depth, int width)
82	    {
83	        boolean isSizeImpossible = depth <= 0 || depth <= 0;
84	        
85	        if (isSizeImpossible)
86	        {
87	            System.out.println("The dimensions must be greater than zero.");
88	            System.out.println("Using default values.");
89	            
90	            depth = DEFAULT_DEPTH;
91	            width = DEFAULT_WIDTH;
92	        }
93	        
94	        actors = new ArrayList<>();
95	        field = new Field(depth, width);
96	        
97	        // Set the initial weather:
98	        WeatherSystem.changeToNextDay();
99	
100	        // Create a view of the state of each location in the field:
101	        view = new SimulatorView(this,depth, width);
102	        
103	        view.setColor(Grasshopper.class, GRASSHOPPER_COLOR);
104	        view.setColor(HarvesterAnt.class, HARVESTER_ANT_COLOR);
105	        view.setColor(Termite.class, TERMITE_COLOR);
106	        view.setColor(Impala.class, IMPALA_COLOR);
107	        view.setColor(Pangolin.class, PANGOLIN_COLOR);
108	        view.setColor(Aardvark.class, AARDVARK_COLOR);
109	        view.setColor(Mongoose.class, MONGOOSE_COLOR);
110	        view.setColor(StarGrass.class, STAR_GRASS_COLOR);
111	        view.setColor(RedOatGrass.class, RED_OAT_GRASS_COLOR);
112	        view.setColor(Acacia.class, ACACIA_COLOR);
113	        view.setColor(Carcass.class, CARCASS_COLOR);
114	        
115	        // Show the statistics window:
116	        new Thread(() -> {
117	            Application.launch(StatisticsView.class);
118	        }).start();
119	        
120	        // Setup a valid starting point:
121	        reset();
122	    }
123	    
124	    /**
125	     * @return The current step in the simulation.
126	     */
127	    public static int getCurrentStep() { return step; }
128	    
129	    /**
130	     * @return The current field in the simulation.
131	     */
132	    public static Field getCurrentField() { return field; }
133	    
134	    /**
135	     * Run the simulation from its current state for a reasonably long period,
136	     * (4000 steps).
137	     */
138	    public void runLongSimulation()
139	    {
140	        simulate(4000);
141	    }
142	    
143	    /**
144	     * Run the simulation from its current state for the given number of steps.
145	     * Stop before the given number of steps if it ceases to be viable.
146	     * 
147	     * @param numSteps The number of steps to run for.
148	     */
149	    public void simulate(int numSteps)
150	    {
151	        for (int step = 1; step <= numSteps && view.isViable(field); step++)
152	        {
153	            simulateOneStep();
154	            //delay(60);   // uncomment this to run more slowly
155	        }
156	    }
157	    
158	    /**
159	     * Run the simulation from its current state for a single step.
160	     * Iterate over the whole field updating the state of each
161	     * fox and rabbit.
162	     */
163	    public void simulateOneStep()
164	    {
165	        step++;
166	        
167	        // Update the weather:
168	        if (TimeSystem.hasDayChanged())
169	        {
170	            WeatherSystem.changeToNextDay();
171	            
172	        }
173	
174	        // Provide space for newborn actors:
175	        List<Actor> newActors = new ArrayList<>();
176	        
177	        // Let all rabbits act:
178	        for (Iterator<Actor> it = actors.iterator(); it.hasNext(); )
179	        {
180	            Actor actor = it.next();
181	            
182	            actor.act(newActors);
183	            
184	            if(!actor.getIsAlive()) it.remove();
185	        }
186	               
187	        // Add the newly born foxes and rabbits to the main lists:
188	        actors.addAll(newActors);
189	
190	        view.showStatus(step, field);
191	    }
192	        
193	    /**
194	     * Reset the simulation to a starting position.
195	     */
196	    public void reset()
197	    {
198	        step = 0;
199	        actors.clear();
200	        populate();
201	        
202	        // Show the starting state in the view:
203	        view.showStatus(step, field);
204	        
205	        // Toggle boolean to show StatisticsView should be reset:
206	        resetStatisticsView = true;
207	    }
208	    
209	    /**
210	     * Randomly populate the field with foxes and rabbits.
211	     */
212	    private void populate()
213	    {
214	        Random rand = Randomizer.getRandom();
215	        field.clear();
216	        
217	        for (int row = 0; row < field.getDepth(); row++)
218	        {
219	            for (int col = 0; col < field.getWidth(); col++)
220	            {
221	                Location location = new Location(row, col);
222	                Actor actor;
223	                
224	                // Refactor this?
225	                if (rand.nextDouble() <= GRASSHOPPER_CREATION_PROBABILITY)
226	                    actors.add(new Grasshopper(true, field, location));
227	                else if (rand.nextDouble() <= HARVESTER_ANT_CREATION_PROBABILITY)
228	                    actors.add(new HarvesterAnt(true, field, location));
229	                else if (rand.nextDouble() <= TERMITE_CREATION_PROBABILITY)
230	                    actors.add(new Termite(true, field, location));
231	                else if (rand.nextDouble() <= IMPALA_CREATION_PROBABILITY)
232	                    actors.add(new Impala(true, field, location));
233	                else if (rand.nextDouble() <= PANGOLIN_CREATION_PROBABILITY)
234	                    actors.add(new Pangolin(true, field, location));
235	                else if (rand.nextDouble() <= AARDVARK_CREATION_PROBABILITY)
236	                    actors.add(new Aardvark(true, field, location));
237	                else if (rand.nextDouble() <= MONGOOSE_CREATION_PROBABILITY)
238	                    actors.add(new Mongoose(true, field, location));
239	                else if (rand.nextDouble() <= STAR_GRASS_CREATION_PROBABILITY)
240	                    actors.add(new StarGrass(field, location));
241	                else if (rand.nextDouble() <= RED_OAT_GRASS_CREATION_PROBABILITY)
242	                    actors.add(new RedOatGrass(field, location));
243	                else if (rand.nextDouble() <= ACACIA_CREATION_PROBABILITY)
244	                    actors.add(new Acacia(field, location));
245	                
246	                // Else leave the location empty.
247	            }
248	        }
249	    }
250	    
251	    /**
252	     * Pause for a given time.
253	     * 
254	     * @param millisec The time to pause for, in milliseconds
255	     */
256	    private void delay(int millisec)
257	    {
258	        try
259	        {
260	            Thread.sleep(millisec);
261	        }
262	        catch (InterruptedException ie)
263	        {
264	            // Wake up.
265	        }
266	    }
267	}
