1	import java.util.Collections;
2	import java.util.Iterator;
3	import java.util.LinkedList;
4	import java.util.List;
5	import java.util.Random;
6	
7	/**
8	 * Represent a rectangular grid of field positions.
9	 * Each position is able to store a single actor.
10	 *
11	 * @version 18.02.22 (DD:MM:YY)
12	 */
13	public class Field
14	{
15	    // A random number generator for providing random locations:
16	    private static final Random rand = Randomizer.getRandom();
17	    // The depth and width of the field:
18	    private int depth, width;
19	    // Storage for the actors:
20	    private Object[][] field;
21	    private Field producerField;
22	    
23	    /**
24	     * Represent a field of the given dimensions.
25	     * 
26	     * @param depth The depth of the field.
27	     * @param width The width of the field.
28	     */
29	    public Field(int depth, int width)
30	    {
31	        this.depth = depth;
32	        this.width = width;
33	        
34	        field = new Object[depth][width];
35	    }
36	    
37	    /**
38	     * Empty the field.
39	     */
40	    public void clear()
41	    {
42	        for (int row = 0; row < depth; row++)
43	        {
44	            for (int col = 0; col < width; col++)
45	            {
46	                field[row][col] = null;
47	            }
48	        }
49	    }
50	    
51	    /**
52	     * Clear the given location.
53	     * 
54	     * @param location The location to clear.
55	     */
56	    public void clear(Location location)
57	    {
58	        field[location.getRow()][location.getCol()] = null;
59	    }
60	    
61	    /**
62	     * Place an actor at the given location.
63	     * If there is already an actor at the location it will
64	     * be lost.
65	     * 
66	     * @param actor The actor to be placed.
67	     * @param row   Row coordinate of the location.
68	     * @param col   Column coordinate of the location.
69	     */
70	    public void place(Object actor, int row, int col)
71	    {
72	        place(actor, new Location(row, col));
73	    }
74	    
75	    /**
76	     * Place an actor at the given location.
77	     * If there is already an actor at the location it will
78	     * be lost.
79	     * @param actor The actor to be placed.
80	     * @param location Where to place the actor.
81	     */
82	    public void place(Object actor, Location location)
83	    {
84	        field[location.getRow()][location.getCol()] = actor;
85	    }
86	    
87	    /**
88	     * Return the actor at the given location, if any.
89	     * 
90	     * @param location Where in the field.
91	     * @return The actor at the given location, or null if there is none.
92	     */
93	    public Object getObjectAt(Location location)
94	    {
95	        return getObjectAt(location.getRow(), location.getCol());
96	    }
97	    
98	    /**
99	     * Return the actor at the given location, if any.
100	     * 
101	     * @param row The desired row.
102	     * @param col The desired column.
103	     * @return The actor at the given location, or null if there is none.
104	     */
105	    public Object getObjectAt(int row, int col)
106	    {
107	        return field[row][col];
108	    }
109	    
110	    /**
111	     * Generate a random location that is adjacent to the
112	     * given location, or is the same location.
113	     * The returned location will be within the valid bounds
114	     * of the field.
115	     * @param location The location from which to generate an adjacency.
116	     * @return A valid location within the grid area.
117	     */
118	    public Location randomAdjacentLocation(Location location)
119	    {
120	        List<Location> adjacent = adjacentLocations(location);
121	        return adjacent.get(0);
122	    }
123	    
124	    /**
125	     * Get a shuffled list of the free adjacent locations.
126	     * 
127	     * @param searchLocation Get locations adjacent to this.
128	     * @return A list of free adjacent locations.
129	     */
130	    public List<Location> getFreeAdjacentLocations(Location searchLocation)
131	    {
132	        // The list of free locations to be returned:
133	        List<Location> free = new LinkedList<>();
134	        
135	        List<Location> adjacentLocations = adjacentLocations(searchLocation);
136	        
137	        for (Location location : adjacentLocations)
138	            if (getObjectAt(location) == null) free.add(location);
139	        
140	        return free;
141	    }
142	    
143	    /**
144	     * Try to find a free location that is adjacent to the
145	     * given location. If there is none, return null.
146	     * The returned location will be within the valid bounds
147	     * of the field.
148	     * 
149	     * @param searchLocation The location from which to generate an adjacency.
150	     * @return A valid location within the grid area.
151	     */
152	    public Location freeAdjacentLocation(Location searchLocation)
153	    {
154	        // Get a list of the free locations:
155	        List<Location> free = getFreeAdjacentLocations(searchLocation);
156	        
157	        // Return the first free location or null if there are none:
158	        if (free.size() > 0) return free.get(0);
159	        else                 return null;
160	    }
161	
162	    /**
163	     * Return a shuffled list of locations adjacent to the given one.
164	     * The list will not include the location itself.
165	     * All locations will lie within the grid.
166	     * 
167	     * @param location The location from which to generate adjacencies.
168	     * @return A list of locations adjacent to that given.
169	     */
170	    public List<Location> adjacentLocations(Location location)
171	    {
172	        assert location != null : "Null location passed to adjacentLocations";
173	        
174	        // The list of locations to be returned:
175	        List<Location> locations = new LinkedList<>();
176	        
177	        if (location != null)
178	        {
179	            int row = location.getRow();
180	            int col = location.getCol();
181	            
182	            for (int roffset = -1; roffset <= 1; roffset++)
183	            {
184	                int nextRow = row + roffset;
185	                
186	                if (nextRow >= 0 && nextRow < depth)
187	                {
188	                    for (int coffset = -1; coffset <= 1; coffset++)
189	                    {
190	                        int nextCol = col + coffset;
191	                        
192	                        // Exclude invalid locations and the original location:
193	                        if (nextCol >= 0 && nextCol < width && (roffset != 0 || coffset != 0))
194	                        {
195	                            locations.add(new Location(nextRow, nextCol));
196	                        }
197	                    }
198	                }
199	            }
200	            
201	            // Shuffle the list. Several other methods rely on the list
202	            // being in a random order:
203	            Collections.shuffle(locations, rand);
204	        }
205	        return locations;
206	    }
207	
208	    /**
209	     * @return The depth of the field.
210	     */
211	    public int getDepth() { return depth; }
212	    
213	    /**
214	     * @return The width of the field.
215	     */
216	    public int getWidth() { return width; }
217	    public Field createProducerField()
218	    {
219	         producerField = new Field(width,depth);
220	         return producerField;
221	    }
222	    public Field getProducerField()
223	    {
224	        return producerField;
225	    }
226	}
