1	import java.awt.Color;
2	import java.util.HashMap;
3	
4	/**
5	 * This class collects and provides some statistical data on the state 
6	 * of a field. It is flexible: it will create and maintain a counter 
7	 * for any class of object that is found within the field.
8	 *
9	 * @version 18.02.22 (DD:MM:YY)
10	 */
11	public class FieldStats
12	{
13	    // Counters for each type of actor in the simulation:
14	    private static HashMap<Class, Counter> counters;
15	    // Whether the counters are currently up to date:
16	    private static boolean areCountsValid;
17	
18	    /**
19	     * Construct a FieldStats object.
20	     */
21	    public FieldStats()
22	    {
23	        // Set up a collection for counters for each type of actor that
24	        // we might find:
25	        counters = new HashMap<>();
26	        areCountsValid = true;
27	    }
28	
29	    /**
30	     * @return A string describing what is in the field.
31	     */
32	    public String getPopulationDetails(Field field)
33	    {
34	        StringBuffer buffer = new StringBuffer();
35	        
36	        if (!areCountsValid) generateCounts(field);
37	        
38	        String prefix = "";
39	        
40	        for (Class key : counters.keySet())
41	        {
42	            Counter info = counters.get(key);
43	            
44	            buffer.append(prefix);
45	            buffer.append(info.getName());
46	            buffer.append(": ");
47	            buffer.append(info.getCount());
48	            
49	            prefix = ", ";
50	        }
51	        
52	        
53	        
54	        return buffer.toString();
55	    }
56	    
57	    /**
58	     * @return The counters representing population numbers.
59	     */
60	    public static HashMap<Class, Counter> getCounters(Field field)
61	    {
62	        if (!areCountsValid) generateCounts(field);
63	        return counters;
64	    }
65	    
66	    /**
67	     * Invalidate the current set of statistics; reset all 
68	     * counts to zero.
69	     */
70	    public static void reset()
71	    {
72	        areCountsValid = false;
73	        
74	        for (Class key : counters.keySet())
75	        {
76	            Counter count = counters.get(key);
77	            
78	            count.reset();
79	        }
80	    }
81	
82	    /**
83	     * Increment the count for one class of actor.
84	     * 
85	     * @param actorClass The class of actor to increment.
86	     */
87	    public static void incrementCount(Class actorClass)
88	    {
89	        Counter count = counters.get(actorClass);
90	        
91	        if (count == null)
92	        {
93	            // We do not have a counter for this species yet.
94	            // Create one:
95	            count = new Counter(actorClass.getName());
96	            
97	            counters.put(actorClass, count);
98	        }
99	        
100	        count.increment();
101	    }
102	
103	    /**
104	     * Indicate that an actor count has been completed.
105	     */
106	    public void countFinished() { areCountsValid = true; }
107	
108	    /**
109	     * Determine whether the simulation is still viable.
110	     * I.e., should it continue to run.
111	     * 
112	     * @return True if there is more than one species alive.
113	     */
114	    public boolean isViable(Field field)
115	    {
116	        // How many counts are non-zero:
117	        int nonZero = 0;
118	        
119	        if (!areCountsValid) generateCounts(field);
120	        
121	        for (Class key : counters.keySet())
122	        {
123	            Counter info = counters.get(key);
124	            
125	            if (info.getCount() > 0) nonZero++;
126	        }
127	        
128	        return nonZero > 1;
129	    }
130	    
131	    /**
132	     * Generate counts of the number of actors.
133	     * These are not kept up to date as actors are placed in the
134	     * field, but only when a request is made for the information.
135	     * 
136	     * @param field The field to generate the stats for.
137	     */
138	    private static void generateCounts(Field field)
139	    {
140	        reset();
141	        
142	        for (int row = 0; row < field.getDepth(); row++)
143	        {
144	            for (int col = 0; col < field.getWidth(); col++)
145	            {
146	                Object actor = field.getObjectAt(row, col);
147	                
148	                if (actor != null) incrementCount(actor.getClass());
149	            }
150	        }
151	        
152	        areCountsValid = true;
153	    }
154	}
