1	import javafx.application.Application;
2	import javafx.stage.Stage;
3	import javafx.scene.Scene;
4	import javafx.scene.layout.Pane;
5	import javafx.scene.layout.BorderPane;
6	import javafx.scene.control.Label;
7	import javafx.scene.chart.LineChart;
8	import javafx.scene.chart.NumberAxis;
9	import javafx.geometry.Insets;
10	import javafx.animation.Timeline;
11	import javafx.animation.KeyFrame;
12	import javafx.util.Duration;
13	import javafx.scene.chart.XYChart.Series;
14	import javafx.scene.chart.XYChart.Data;
15	import java.util.HashMap;
16	
17	/**
18	 * A graphical view of the population of each species over time as the
19	 * simulation runs its courses.
20	 *
21	 * @version 18.02.22 (DD:MM:YY)
22	 */
23	public class StatisticsView extends Application
24	{
25	    // Constants representing the JavaFX window properties:
26	    //   The default size of the window:
27	    private static final int WINDOW_WIDTH = 800;
28	    private static final int WINDOW_HEIGHT = 600;
29	    //   The default title of the window:
30	    private static final String WINDOW_TITLE = "Statistics";
31	    
32	    // Constants representing JavaFX GUI components:
33	    //   The root layout component:
34	    private static BorderPane root;
35	    //   An informational label explaining the window:
36	    private static Label infoLabel;
37	    //   The line chart showing populations:
38	    private static LineChart lineChart;
39	    //   The axes of the population line chart:
40	    private static NumberAxis xAxis, yAxis;
41	    //   The XYSeries representing each population over time:
42	    private static HashMap<Class, Series> actorXYSeries = new HashMap();
43	    
44	    // The time between updates for the stats:
45	    private static double updateTimeInSeconds = 0.1;
46	    // The last day recorded:
47	    private static int lastDayRecorded = -1; // Set to -1 so we record day 0
48	    // The highest recorded population:
49	    private static int highestPopulation = 0;
50	    
51	    /**
52	     * @param stage The stage (window) for JavaFX.
53	     */
54	    @Override
55	    public void start(Stage stage)
56	    {
57	        // Create the root layout component:
58	        root = new BorderPane();
59	        
60	        // Create the scene:
61	        Scene scene = new Scene(root, WINDOW_WIDTH, WINDOW_HEIGHT);
62	        
63	        // Create the informational label:
64	        infoLabel = new Label("The chart below shows the population of each species over time:");
65	        
66	        // Create the line chart:
67	        lineChart = getPopulationLineChart();
68	        lineChart.setAnimated(false);
69	        
70	        // Set the initial properties of the root BorderPane:
71	        final int ROOT_PADDING = 5;
72	        root.setTop(infoLabel);
73	        root.setCenter(lineChart);
74	        root.setPadding(new Insets(ROOT_PADDING, ROOT_PADDING, ROOT_PADDING, ROOT_PADDING));
75	        
76	        // Set the initial properties of the stage and show it:
77	        stage.setScene(scene);
78	        stage.setTitle(WINDOW_TITLE);
79	        stage.show();
80	        
81	        // Create a timeline to update the population line chart at a fixed rate:
82	        KeyFrame keyFrame = new KeyFrame(Duration.millis(updateTimeInSeconds * 1000), e -> updatePopulationLineChart());
83	        Timeline timeline = new Timeline(keyFrame);
84	        timeline.setCycleCount(Timeline.INDEFINITE);
85	        timeline.play();
86	    }
87	    
88	    /**
89	     * Create a line chart for the population.
90	     * 
91	     * @return A line chart representing population.
92	     */
93	    private static LineChart getPopulationLineChart()
94	    {
95	        // Create the axes:
96	        final int xAxisStep = 5;
97	        final int yAxisStep = 1000;
98	        xAxis = new NumberAxis(0, 0, xAxisStep);
99	        yAxis = new NumberAxis(0, 0, yAxisStep);
100	        xAxis.setLabel("Days");
101	        yAxis.setLabel("Population");
102	        
103	        // Create the line chart itself:
104	        return new LineChart(xAxis, yAxis);
105	    }
106	    
107	    /**
108	     * Update the data for the population line chart. This is called
109	     * periodically.
110	     */
111	    private void updatePopulationLineChart()
112	    {
113	        // Reset if necessary:
114	        if (Simulator.resetStatisticsView)
115	        {
116	            resetPopulationLineChart();
117	            Simulator.resetStatisticsView = false;
118	        }
119	        
120	        // Guard statement: Don't continue with this if the day
121	        // hasn't changed since the last update:
122	        if (lastDayRecorded == TimeSystem.getCurrentDay()) return;
123	        
124	        // Iterate through each counter in FieldStats:
125	        Field field = Simulator.getCurrentField();
126	        HashMap<Class, Counter> counters = FieldStats.getCounters(field);
127	        
128	        for (Class key : counters.keySet())
129	        {
130	            Counter counter = counters.get(key);
131	            
132	            // Get the new data to add to the XYSeries:
133	            Data newData = new Data(TimeSystem.getCurrentDay(), counter.getCount());
134	            
135	            // Create a new XYSeries for this actor if there is none already:
136	            if (!actorXYSeries.containsKey(key))
137	            {
138	                Series series = new Series();
139	                series.setName(counter.getName());
140	                
141	                lineChart.getData().add(series);
142	                
143	                actorXYSeries.put(key, series);
144	            }
145	            
146	            // Update the XYSeries for this Actor:
147	            Series series = actorXYSeries.get(key);
148	            series.getData().add(newData); 
149	            
150	            // Update the highest population if necessary:
151	            if (counter.getCount() > highestPopulation) highestPopulation = counter.getCount();
152	        }
153	        
154	        // Set the new last day recorded:
155	        lastDayRecorded = TimeSystem.getCurrentDay();
156	        
157	        // Set the upper bounds for each of the axes:
158	        xAxis.setUpperBound(TimeSystem.getCurrentDay());
159	        yAxis.setUpperBound(highestPopulation);
160	    }
161	    
162	    /**
163	     * Reset the population line chart.
164	     */
165	    public static void resetPopulationLineChart()
166	    {
167	        lineChart = getPopulationLineChart();
168	        root.setCenter(lineChart);
169	        
170	        lineChart.getData().clear();
171	        
172	        actorXYSeries.clear();
173	        
174	        lastDayRecorded = -1;
175	        
176	        highestPopulation = 0;
177	    }
178	}

1	/**
2	 * A system that keeps track of time and the current day.
3	 *
4	 * @version 18.02.22 (DD:MM:YY)
5	 */
6	public class TimeSystem
7	{
8	    // The last recorded day:
9	    private static int lastRecordedDay = 0;
10	    
11	    /**
12	     * @return The current day.
13	     */
14	    public static int getCurrentDay()
15	    {
16	        int currentDay = (int) (Simulator.getCurrentStep() / Simulator.NUMBER_OF_STEPS_PER_DAY);
17	        
18	        return currentDay;
19	    }
20	    
21	    /**
22	     * @return Whether or not the day has changed since it was last checked.
23	     */
24	    public static boolean hasDayChanged()
25	    {
26	        if (getCurrentDay() != lastRecordedDay)
27	        {
28	            lastRecordedDay = getCurrentDay();
29	            
30	            return true;
31	        }
32	        else
33	        {
34	            return false;
35	        }
36	    }
37	    
38	    /**
39	     * @return Whether or not it is currently night time.
40	     */
41	    public static boolean isNightTime()
42	    {
43	        // Calculate the time of day:
44	        double preciseCurrentDay = ((double)Simulator.getCurrentStep() / Simulator.NUMBER_OF_STEPS_PER_DAY);
45	        
46	        double timeOfDay = preciseCurrentDay - getCurrentDay(); // Between 0.0 and 1.0
47	        
48	        // If time is between 0.8 and 1.0 or 0.0 and 0.2, it is night:
49	        if ((timeOfDay > 0.8 && timeOfDay < 1.0) || (timeOfDay > 0.0 && timeOfDay < 0.2))
50	            return true;
51	        else
52	            return false;
53	    }
54	}

