3	/**
4	 * A class representing shared characteristics of animals.
5	 *
6	 * @version 2016.02.29 (2)
7	 */
8	public abstract class Animal
9	{
10	    // Whether the animal is alive or not.
11	    private boolean alive;
12	    // The animal's field.
13	    private Field field;
14	    // The animal's position in the field.
15	    private Location location;
16	    
17	    /**
18	     * Create a new animal at location in field.
19	     * 
20	     * @param field The field currently occupied.
21	     * @param location The location within the field.
22	     */
23	    public Animal(Field field, Location location)
24	    {
25	        alive = true;
26	        this.field = field;
27	        setLocation(location);
28	    }
29	    
30	    /**
31	     * Make this animal act - that is: make it do
32	     * whatever it wants/needs to do.
33	     * @param newAnimals A list to receive newly born animals.
34	     */
35	    abstract public void act(List<Animal> newAnimals);
36	
37	    /**
38	     * Check whether the animal is alive or not.
39	     * @return true if the animal is still alive.
40	     */
41	    protected boolean isAlive()
42	    {
43	        return alive;
44	    }
45	
46	    /**
47	     * Indicate that the animal is no longer alive.
48	     * It is removed from the field.
49	     */
50	    protected void setDead()
51	    {
52	        alive = false;
53	        if(location != null) {
54	            field.clear(location);
55	            location = null;
56	            field = null;
57	        }
58	    }
59	
60	    /**
61	     * Return the animal's location.
62	     * @return The animal's location.
63	     */
64	    protected Location getLocation()
65	    {
66	        return location;
67	    }
68	    
69	    /**
70	     * Place the animal at the new location in the given field.
71	     * @param newLocation The animal's new location.
72	     */
73	    protected void setLocation(Location newLocation)
74	    {
75	        if(location != null) {
76	            field.clear(location);
77	        }
78	        location = newLocation;
79	        field.place(this, newLocation);
80	    }
81	    
82	    /**
83	     * Return the animal's field.
84	     * @return The animal's field.
85	     */
86	    protected Field getField()
87	    {
88	        return field;
89	    }
90	}
