1	import java.util.List;
2	import java.util.Random;
3	
4	/**
5	 * A simple model of a rabbit.
6	 * Rabbits age, move, breed, and die.
7	 *
8	 * @version 2016.02.29 (2)
9	 */
10	public class Rabbit extends Animal
11	{
12	    // Characteristics shared by all rabbits (class variables).
13	
14	    // The age at which a rabbit can start to breed.
15	    private static final int BREEDING_AGE = 5;
16	    // The age to which a rabbit can live.
17	    private static final int MAX_AGE = 40;
18	    // The likelihood of a rabbit breeding.
19	    private static final double BREEDING_PROBABILITY = 0.12;
20	    // The maximum number of births.
21	    private static final int MAX_LITTER_SIZE = 4;
22	    // A shared random number generator to control breeding.
23	    private static final Random rand = Randomizer.getRandom();
24	    
25	    // Individual characteristics (instance fields).
26	    
27	    // The rabbit's age.
28	    private int age;
29	
30	    /**
31	     * Create a new rabbit. A rabbit may be created with age
32	     * zero (a new born) or with a random age.
33	     * 
34	     * @param randomAge If true, the rabbit will have a random age.
35	     * @param field The field currently occupied.
36	     * @param location The location within the field.
37	     */
38	    public Rabbit(boolean randomAge, Field field, Location location)
39	    {
40	        super(field, location);
41	        age = 0;
42	        if(randomAge) {
43	            age = rand.nextInt(MAX_AGE);
44	        }
45	    }
46	    
47	    /**
48	     * This is what the rabbit does most of the time - it runs 
49	     * around. Sometimes it will breed or die of old age.
50	     * @param newRabbits A list to return newly born rabbits.
51	     */
52	    public void act(List<Animal> newRabbits)
53	    {
54	        incrementAge();
55	        if(isAlive()) {
56	            giveBirth(newRabbits);            
57	            // Try to move into a free location.
58	            Location newLocation = getField().freeAdjacentLocation(getLocation());
59	            if(newLocation != null) {
60	                setLocation(newLocation);
61	            }
62	            else {
63	                // Overcrowding.
64	                setDead();
65	            }
66	        }
67	    }
68	
69	    /**
70	     * Increase the age.
71	     * This could result in the rabbit's death.
72	     */
73	    private void incrementAge()
74	    {
75	        age++;
76	        if(age > MAX_AGE) {
77	            setDead();
78	        }
79	    }
80	    
81	    /**
82	     * Check whether or not this rabbit is to give birth at this step.
83	     * New births will be made into free adjacent locations.
84	     * @param newRabbits A list to return newly born rabbits.
85	     */
86	    private void giveBirth(List<Animal> newRabbits)
87	    {
88	        // New rabbits are born into adjacent locations.
89	        // Get a list of adjacent free locations.
90	        Field field = getField();
91	        List<Location> free = field.getFreeAdjacentLocations(getLocation());
92	        int births = breed();
93	        for(int b = 0; b < births && free.size() > 0; b++) {
94	            Location loc = free.remove(0);
95	            Rabbit young = new Rabbit(false, field, loc);
96	            newRabbits.add(young);
97	        }
98	    }
99	        
100	    /**
101	     * Generate a number representing the number of births,
102	     * if it can breed.
103	     * @return The number of births (may be zero).
104	     */
105	    private int breed()
106	    {
107	        int births = 0;
108	        if(canBreed() && rand.nextDouble() <= BREEDING_PROBABILITY) {
109	            births = rand.nextInt(MAX_LITTER_SIZE) + 1;
110	        }
111	        return births;
112	    }
113	
114	    /**
115	     * A rabbit can breed if it has reached the breeding age.
116	     * @return true if the rabbit can breed, false otherwise.
117	     */
118	    private boolean canBreed()
119	    {
120	        return age >= BREEDING_AGE;
121	    }
122	}
