import java.util.*;
public class Equiv {
    // probabilities in the SAME order as the original if/else chain & new SPECIES list
    static final double[] P = {0.15,0.25,0.21,0.15,0.125,0.12,0.12,0.05,0.04,0.04};
    static final String[] N = {"Grasshopper","HarvesterAnt","Termite","Impala","Pangolin","Aardvark","Mongoose","StarGrass","RedOatGrass","Acacia"};

    static String oldWay(Random r){
        if(r.nextDouble()<=P[0])return N[0];
        else if(r.nextDouble()<=P[1])return N[1];
        else if(r.nextDouble()<=P[2])return N[2];
        else if(r.nextDouble()<=P[3])return N[3];
        else if(r.nextDouble()<=P[4])return N[4];
        else if(r.nextDouble()<=P[5])return N[5];
        else if(r.nextDouble()<=P[6])return N[6];
        else if(r.nextDouble()<=P[7])return N[7];
        else if(r.nextDouble()<=P[8])return N[8];
        else if(r.nextDouble()<=P[9])return N[9];
        return "(empty)";
    }
    static String newWay(Random r){
        for(int i=0;i<P.length;i++){ if(r.nextDouble()<=P[i]) return N[i]; }
        return "(empty)";
    }
    public static void main(String[] a){
        long seed=10001;            // same seed Randomizer uses
        Random ro=new Random(seed), rn=new Random(seed);
        int cells=120*160, mism=0;
        for(int c=0;c<cells;c++){
            String o=oldWay(ro), n=newWay(rn);
            if(!o.equals(n)){ mism++; if(mism<=5) System.out.println("MISMATCH cell "+c+": old="+o+" new="+n); }
        }
        // also confirm both consumed the random stream identically (next draw equal)
        boolean streamAligned = ro.nextDouble()==rn.nextDouble();
        System.out.println("cells="+cells+" mismatches="+mism+" streamAligned="+streamAligned);
        System.out.println(mism==0 && streamAligned ? "PASS: behaviour identical" : "FAIL");
    }
}
